import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        long number = Long.parseLong(reader.readLine());
        System.out.println(calculateOnesCount(number));
    }

    private static int getNumberOfDigits(long n) {
        return (int) Math.log10(n) + 1;
    }

    private static long buildOneSequence(int length) {
        long sequence = 1;
        for (int i = 1; i < length; i++) {
            sequence = sequence * 10 + 1;
        }
        return sequence;
    }

    private static long calculateOnesCount(long n) {
        if (n <= 6) return n;
        int digitsCount = getNumberOfDigits(n);
        long baseSequence = buildOneSequence(digitsCount);
        long totalSum = baseSequence;
        int count = 0;
        long remaining = n;

        while (totalSum < n) {
            count++;
            remaining = n - totalSum;
            totalSum += buildOneSequence(digitsCount);
        }

        long result;
        if (count > 0)
            result = Math.min(count * digitsCount + calculateOnesCount(remaining),
                              (count + 1) * digitsCount + calculateOnesCount(totalSum - n));
        else
            result = (count + 1) * digitsCount + calculateOnesCount(totalSum - n);

        long nextSequence = buildOneSequence(digitsCount + 1);
        if (nextSequence - n < n)
            result = Math.min(result, digitsCount + 1 + calculateOnesCount(nextSequence - n));
        return result;
    }
}
